/// Requirement: FieldBoundary { field: "cmode", value: 1, boundary: PowerOfTwo }
/// value 1
#[test]
fn test_aarch32_vmvn_i_t2a2_a_field_cmode_1_poweroftwo_830_ef800130() {
    // Thumb encoding (32): 0xEF800130
    // Test aarch32_VMVN_i_T2A2_A field cmode = 1 (PowerOfTwo)
    // ISET: T32
    // Fields: Vd=0, Q=0, imm4=0, i=0, D=0, cmode=1, imm3=0
    let mut cpu = create_thumb_cpu();
    let encoding: u32 = 0xEF800130;
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "T32 instruction should execute successfully"
    );
}

