/// Requirement: FieldBoundary { field: "M", value: 0, boundary: Min }
/// minimum value
#[test]
fn test_aarch32_vcge_r_t1a1_a_field_m_0_min_310_f2000310() {
    // Encoding: 0xF2000310
    // Test aarch32_VCGE_r_T1A1_A field M = 0 (Min)
    // ISET: A32
    // Fields: M=0, U=0, size=0, Vm=0, Vd=0, Q=0, N=0, D=0, Vn=0
    let encoding: u32 = 0xF2000310;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

