/// Requirement: FieldBoundary { field: "Vd", value: 1, boundary: PowerOfTwo }
/// SIMD register V1
#[test]
fn test_aarch32_vabd_i_t2a2_a_field_vd_1_poweroftwo_700_f2801700() {
    // Encoding: 0xF2801700
    // Test aarch32_VABD_i_T2A2_A field Vd = 1 (PowerOfTwo)
    // ISET: A32
    // Fields: Vm=0, size=0, D=0, M=0, Vd=1, N=0, U=0, Vn=0
    let encoding: u32 = 0xF2801700;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

