/// Requirement: FieldBoundary { field: "M", value: 0, boundary: Min }
/// minimum value
#[test]
fn test_aarch32_vcnt_t1a1_a_field_m_0_min_500_f3b00500() {
    // Encoding: 0xF3B00500
    // Test aarch32_VCNT_T1A1_A field M = 0 (Min)
    // ISET: A32
    // Fields: Vm=0, M=0, size=0, Q=0, D=0, Vd=0
    let encoding: u32 = 0xF3B00500;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

