/// Requirement: FieldSpecial { field: "S", value: 0, meaning: "Size variant 0" }
/// Size variant 0
#[test]
fn test_aarch32_vcmla_idx_a1_a_special_s_0_size_variant_0_2048_fe000800() {
    // Encoding: 0xFE000800
    // Test aarch32_VCMLA_idx_A1_A special value S = 0 (Size variant 0)
    // ISET: A32
    // Fields: D=0, Vm=0, Vd=0, M=0, Vn=0, Q=0, S=0, rot=0, N=0
    let encoding: u32 = 0xFE000800;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

