/// Requirement: FieldExtraction { field: "combination", bit_start: 0, bit_width: 32 }
/// U=0 (minimum value)
#[test]
fn test_aarch32_vqadd_t1a1_a_combo_0_10_f2000010() {
    // Encoding: 0xF2000010
    // Test aarch32_VQADD_T1A1_A field combination: U=0, D=0, size=0, Vn=0, Vd=0, N=0, Q=0, M=0, Vm=0
    // ISET: A32
    // Fields: Vn=0, Vm=0, D=0, Vd=0, N=0, Q=0, size=0, M=0, U=0
    let encoding: u32 = 0xF2000010;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

