/// power of 2 (2^3 = 8)
#[test]
fn test_aarch32_vdup_s_t1a1_a_field_imm4_8_poweroftwo_c00_f3b80c00() {
    // Encoding: 0xF3B80C00
    // Test aarch32_VDUP_s_T1A1_A field imm4 = 8 (PowerOfTwo)
    // ISET: A32
    // Fields: Vm=0, Q=0, M=0, Vd=0, imm4=8, D=0
    let encoding: u32 = 0xF3B80C00;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

