/// Provenance: aarch32_VABS_A1_A
/// ASL: `field D 22 +: 1`
/// Requirement: FieldBoundary { field: "D", value: 0, boundary: Min }
/// minimum value
#[test]
fn test_aarch32_vabs_a1_a_field_d_0_min_300_f3b10300() {
    // Encoding: 0xF3B10300
    // Test aarch32_VABS_A1_A field D = 0 (Min)
    // ISET: A32
    // Fields: size=0, Q=0, Vm=0, F=0, M=0, Vd=0, D=0
    let encoding: u32 = 0xF3B10300;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

