/// condition NE (not equal)
#[test]
fn test_aarch32_vabs_a2_a_field_cond_1_poweroftwo_8c0_1eb008c0() {
    // Encoding: 0x1EB008C0
    // Test aarch32_VABS_A2_A field cond = 1 (PowerOfTwo)
    // ISET: A32
    // Fields: cond=1, D=0, size=0, M=0, Vm=0, Vd=0
    let encoding: u32 = 0x1EB008C0;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

