/// Requirement: FieldBoundary { field: "D", value: 1, boundary: Max }
/// maximum value (1)
#[test]
fn test_aarch32_vcle_i_t1_a_field_d_1_max_180_fff10180() {
    // Thumb encoding (32): 0xFFF10180
    // Test aarch32_VCLE_i_T1_A field D = 1 (Max)
    // ISET: T32
    // Fields: size=0, D=1, Vd=0, F=0, Vm=0, M=0, Q=0
    let mut cpu = create_thumb_cpu();
    let encoding: u32 = 0xFFF10180;
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "T32 instruction should execute successfully"
    );
}

