/// Requirement: FieldBoundary { field: "imm6", value: 3, boundary: PowerOfTwoMinusOne }
/// 2^2 - 1 = 3
#[test]
fn test_aarch32_vshl_i_t1a1_a_field_imm6_3_poweroftwominusone_510_ef830510() {
    // Thumb encoding (32): 0xEF830510
    // Test aarch32_VSHL_i_T1A1_A field imm6 = 3 (PowerOfTwoMinusOne)
    // ISET: T32
    // Fields: Q=0, Vm=0, D=0, Vd=0, M=0, imm6=3, L=0
    let mut cpu = create_thumb_cpu();
    let encoding: u32 = 0xEF830510;
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "T32 instruction should execute successfully"
    );
}

