/// SIMD register V1
#[test]
fn test_aarch32_vcmla_a1_a_field_vn_1_poweroftwo_800_fc210800() {
    // Encoding: 0xFC210800
    // Test aarch32_VCMLA_A1_A field Vn = 1 (PowerOfTwo)
    // ISET: A32
    // Fields: M=0, Q=0, D=0, N=0, Vd=0, rot=0, Vm=0, S=0, Vn=1
    let encoding: u32 = 0xFC210800;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "A32 instruction 0x{:08X} should execute successfully",
        encoding
    );
}

