/// 32-bit / word size
#[test]
fn test_aarch32_vqrshl_t1a1_a_field_size_2_poweroftwo_510_ef200510() {
    // Thumb encoding (32): 0xEF200510
    // Test aarch32_VQRSHL_T1A1_A field size = 2 (PowerOfTwo)
    // ISET: T32
    // Fields: Vm=0, U=0, D=0, Vn=0, Vd=0, size=2, N=0, Q=0, M=0
    let mut cpu = create_thumb_cpu();
    let encoding: u32 = 0xEF200510;
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "T32 instruction should execute successfully"
    );
}

