    // Fields: sz=0, M=0, Vm=0, D=0, N=0, Vd=0, op=0, Vn=0, Q=0
    let encoding: u32 = 0xF3000F10;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
