fn test_aarch32_vpaddl_t1a1_a_invalid_3_200_ffb00200() {
    // Thumb encoding (32): 0xFFB00200
    // Test aarch32_VPADDL_T1A1_A invalid encoding: Unconditional UNDEFINED
    // ISET: T32
    // Fields: op=0, Vm=0, Vd=0, M=0, Q=0, size=0, D=0
    let mut cpu = create_thumb_cpu();
    let encoding: u32 = 0xFFB00200;
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step();
    assert!(
        exit.is_err() || !matches!(exit.unwrap(), CpuExit::Continue),
        "expected UNDEFINED for T32 encoding"
    );
}

/// Provenance: aarch32_VPADDL_T1A1_A
/// ASL: `MOVZ X0, #0x1234, LSL #0`
/// Requirement: RegisterWrite { reg_type: Gp32, dest_field: "Rd" }
/// lower 16 bits (32)
#[test]
fn test_aarch32_vpaddl_t1a1_a_movz_oracle_32_0_f3b24680() {
    // Test MOVZ 32-bit: lower 16 bits (oracle)
    // Encoding: 0xF3B24680
    // ISET: A32
    let mut cpu = create_test_cpu();
    let encoding: u32 = 0xF3B24680;
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(exit, CpuExit::Continue, "instruction should execute");
    assert_eq!(get_w(&cpu, 0), 0x1234, "W0 should be 0x00001234");
}

