/// 0 + 0 = 0 (Z=1)
#[test]
fn test_aarch32_vmrs_t1a1_as_flags_zeroresult_0_0ef00a10() {
    // Test aarch32_VMRS_T1A1_AS flag computation: ZeroResult
    // Encoding: 0x0EF00A10
    // ISET: A32
    let mut cpu = create_test_cpu();
    set_w(&mut cpu, 2, 0x0);
    set_w(&mut cpu, 1, 0x0);
    let encoding: u32 = 0x0EF00A10;
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(exit, CpuExit::Continue, "instruction should execute");
    assert_eq!(cpu.get_pstate().n, false, "N should be false");
    assert_eq!(cpu.get_pstate().z, true, "Z should be true");
    assert_eq!(cpu.get_pstate().c, false, "C should be false");
    assert_eq!(cpu.get_pstate().v, false, "V should be false");
}

